      en: ["Elevation of 3905 meters above sea level.", "Highest point of the Zangezur Mountain range.", "Geologically composed of granite and granodiorite.", "Border peak between Armenia and Nakhchivan.", "Features distinct traces of Pleistocene glaciation.", "Key watershed for the Vorotan and Voghji rivers."],
